type InstitutionRow = {
  id: number;
  institution_name: string | null;
  type: string | null;
  institution_type_id?: number | null;
  institution_type?: {
    id: number;
    name: string | null;
    category?: {
      id: number;
      name: string | null;
    } | null;
  } | null;
  city: string | null;
  district: string | null;
