  source: string | null;
};

function renderMebFallback(title: string, message: string) {
  return (
    <div className="institution-detail-page institution-detail-page--meb">
      <div className="institution-detail-container">
        <h1 className="institution-name">{title}</h1>
        <p>{message}</p>
      </div>
    </div>
