"use client";

import { useState } from "react";
import Link from "next/link";
import { createSupabaseBrowserClient } from "@/lib/supabase/client";
import "@/styles/main.scss";
import "@/styles/pages/auth.scss";

function getPasswordResetRedirectUrl() {
  const envBase = String(process.env.NEXT_PUBLIC_SITE_URL ?? "").trim();
  const base = envBase || window.location.origin;
  return `${base.replace(/\/+$/, "")}/auth/update-password`;
}

export default function ForgotPasswordClient() {
  const [email, setEmail] = useState("");
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [sent, setSent] = useState(false);

  const handleSubmit = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    setError(null);
    setLoading(true);

    try {
      const supabase = createSupabaseBrowserClient();
      const { error: resetError } = await supabase.auth.resetPasswordForEmail(email.trim(), {
        redirectTo: getPasswordResetRedirectUrl(),
      });

      if (resetError) {
        setError(resetError.message || "Sıfırlama e-postası gönderilemedi. Lütfen tekrar deneyin.");
        return;
      }

      setSent(true);
    } catch (_err) {
      setError("Beklenmeyen bir hata oluştu. Lütfen tekrar deneyin.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="auth-content-wrapper">
      <div className="signup-card">
        <h1 className="auth-title">Şifremi Unuttum</h1>
        <p className="auth-subtitle">
          E-posta adresinizi girin, size şifre yenileme bağlantısı gönderelim.
        </p>

        {sent ? (
          <div className="auth-feedback auth-feedback--success" role="status">
            Şifre sıfırlama bağlantısı gönderildi. Lütfen e-posta kutunuzu kontrol edin.
          </div>
        ) : (
          <form className="auth-form" onSubmit={handleSubmit}>
            {error ? (
              <div className="auth-feedback auth-feedback--error" role="alert">
                {error}
              </div>
            ) : null}

            <div className="auth-field">
              <label htmlFor="forgot-email" className="auth-label">
                E-posta Adresi
              </label>
              <input
                id="forgot-email"
                type="email"
                className="auth-input"
                placeholder="eposta@adresiniz.com"
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                disabled={loading}
                required
              />
            </div>

            <button type="submit" className="auth-primary-button" disabled={loading}>
              {loading ? "Gönderiliyor..." : "Sıfırlama Bağlantısı Gönder"}
            </button>
          </form>
        )}

        <p className="auth-bottom-text">
          <Link href="/login" className="auth-link">
            Giriş sayfasına dön
          </Link>
        </p>
      </div>
    </div>
  );
}

"use client";

import { useState, Suspense } from 'react';
import { useRouter, useSearchParams } from 'next/navigation';
import Link from 'next/link';
import { createSupabaseBrowserClient } from '@/lib/supabase/client';
import '@/styles/main.scss';
import '@/styles/pages/auth.scss';

function LoginPageContent() {
  const router = useRouter();
  const searchParams = useSearchParams();
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);

  const handleSubmit = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    setError(null);
    setLoading(true);

    try {
      const supabase = createSupabaseBrowserClient();
      const { data, error: signInError } = await supabase.auth.signInWithPassword({
        email,
        password,
      });

      if (signInError) {
        setError(signInError.message || 'Giriş yapılırken bir hata oluştu.');
        return;
      }

      window.location.href = '/';
    } catch (err) {
      setError('Beklenmeyen bir hata oluştu. Lütfen tekrar deneyin.');
    } finally {
      setLoading(false);
    }
  };

  const authError = searchParams.get('error');
  const resetStatus = searchParams.get('reset');
  const displayError = error || (authError === 'auth_callback_error' ? 'Kimlik doğrulama hatası. Lütfen tekrar deneyin.' : null);
  const displaySuccess = resetStatus === 'success'
    ? 'Şifreniz başarıyla güncellendi. Yeni şifrenizle giriş yapabilirsiniz.'
    : null;

  return (
    <div className="page-container">
      <div className="auth-content-wrapper">
        <div className="auth-main-container">
          <div className="auth-layout">
            <div className="auth-visual">
                <video
                  className="auth-visual-video"
                  src="/gifs/meko_giris.mp4"
                  autoPlay
                  muted
                  loop
                  playsInline
                  aria-label="Giriş görseli"
                />
              {/* auth-orbit
              <div className="auth-orbit">
                <div className="auth-orbit-circle auth-orbit-circle-outer"></div>
                <div className="auth-orbit-circle auth-orbit-circle-inner"></div>
                <div className="auth-orbit-track auth-orbit-track-outer">
                  <div className="auth-orbit-dot"></div>
                </div>
                <div className="auth-orbit-track auth-orbit-track-inner">
                  <div className="auth-orbit-dot"></div>
                </div>
              </div>
              */}
            </div>

            <div className="auth-form-panel">
              <div className="auth-card">
                <h1 className="auth-title">Giriş Yap</h1>
                <p className="auth-subtitle">
                  Hesabınıza giriş yapın ve öğrenme yolculuğunuza devam edin.
                </p>

                <form className="auth-form" onSubmit={handleSubmit}>
                  {displaySuccess && (
                    <div className="auth-feedback auth-feedback--success" role="status">
                      {displaySuccess}
                    </div>
                  )}
                  {displayError && (
                    <div className="auth-feedback auth-feedback--error" role="alert">
                      {displayError}
                    </div>
                  )}

                  <div className="auth-field">
                    <label htmlFor="login-email" className="auth-label">
                      E-posta Adresi
                    </label>
                    <input
                      type="email"
                      id="login-email"
                      name="email"
                      className="auth-input"
                      placeholder="eposta@adresiniz.com"
                      value={email}
                      onChange={(e) => setEmail(e.target.value)}
                      required
                      disabled={loading}
                    />
                  </div>

                  <div className="auth-field">
                    <label htmlFor="login-password" className="auth-label">
                      Şifre
                    </label>
                    <div className="auth-input-with-icon">
                      <input
                        type={showPassword ? 'text' : 'password'}
                        id="login-password"
                        name="password"
                        className="auth-input"
                        placeholder="Şifrenizi girin"
                        value={password}
                        onChange={(e) => setPassword(e.target.value)}
                        required
                        disabled={loading}
                      />
                      <button
                        type="button"
                        className="auth-input-icon"
                        onClick={() => setShowPassword(!showPassword)}
                        aria-label={showPassword ? 'Şifreyi gizle' : 'Şifreyi göster'}
                      >
                        {showPassword ? (
                          <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                            <path d="M17.94 17.94A10.07 10.07 0 0 1 12 20c-7 0-11-8-11-8a18.45 18.45 0 0 1 5.06-5.94M9.9 4.24A9.12 9.12 0 0 1 12 4c7 0 11 8 11 8a18.5 18.5 0 0 1-2.16 3.19m-6.72-1.07a3 3 0 1 1-4.24-4.24"></path>
                            <line x1="1" y1="1" x2="23" y2="23"></line>
                          </svg>
                        ) : (
                          <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                            <path d="M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z"></path>
                            <circle cx="12" cy="12" r="3"></circle>
                          </svg>
                        )}
                      </button>
                    </div>
                  </div>

                  <div style={{ textAlign: 'right' }}>
                    <Link href="/forgot-password" className="auth-link-small">
                      Şifremi unuttum
                    </Link>
                  </div>

                  <button
                    type="submit"
                    className="auth-primary-button"
                    disabled={loading}
                  >
                    {loading ? 'Giriş yapılıyor...' : 'Giriş Yap'}
                  </button>
                </form>

                <p className="auth-bottom-text">
                  Hesabınız yok mu?{' '}
                  <Link href="/signup" className="auth-link">
                    Kayıt olun
                  </Link>
                </p>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

