"use client";

import { useEffect, useState, useRef } from "react";
import Link from "next/link";
import Image from "next/image";
import { Heart } from "lucide-react";
import { getInstitutionDetailHref } from "@/lib/institutionHelpers";
import "@/styles/pages/home.scss";

interface SearchResult {
  id: string | number;
  name: string;
  description: string;
  location: string;
  rating: number;
  reviewCount: number;
  imageUrl: string;
  slug: string;
  source?: string | null;
  badge: {
    icon: string;
    label: string;
    color: string;
  } | null;
}

interface SearchResultsProps {
  query: string;
  onResultClick?: () => void;
  onClearSearch?: () => void;
  onToggleFavorite?: (institutionId: number, e: React.MouseEvent) => void;
  favoriteIds?: Set<number>;
  favoritesEnabled?: boolean;
  favoriteActionLoadingIds?: Set<number>;
  isAuthenticated?: boolean;
}

export default function SearchResults({
  query,
  onResultClick,
  onClearSearch,
  onToggleFavorite,
  favoriteIds,
  favoritesEnabled,
  favoriteActionLoadingIds,
  isAuthenticated,
}: SearchResultsProps) {
  const [results, setResults] = useState<SearchResult[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const abortControllerRef = useRef<AbortController | null>(null);

  useEffect(() => {
    if (abortControllerRef.current) {
      abortControllerRef.current.abort();
    }

    if (!query || query.trim().length < 1) {
      setResults([]);
      setLoading(false);
      setError(null);
      return;
    }

    const timeoutId = setTimeout(() => {
      setLoading(true);
      setError(null);

      abortControllerRef.current = new AbortController();

      fetch(`/api/search/institutions?q=${encodeURIComponent(query.trim())}`, {
        signal: abortControllerRef.current.signal,
      })
        .then((res) => {
          if (!res.ok) {
            throw new Error("Arama başarısız");
          }
          return res.json();
        })
        .then((data) => {
          if (data.error) {
            setError(data.error);
            setResults([]);
          } else {
            setResults(data.results || []);
            setError(null);
          }
        })
        .catch((err) => {
          if (err.name === "AbortError") {
            return;
          }
          console.error("[SearchResults] Error:", err);
          setError("Arama sırasında bir hata oluştu");
          setResults([]);
        })
        .finally(() => {
          setLoading(false);
        });
    }, 300);

    return () => {
      clearTimeout(timeoutId);
      if (abortControllerRef.current) {
        abortControllerRef.current.abort();
      }
    };
  }, [query]);

  if (!query || query.trim().length < 1) {
    return null;
  }

  if (loading) {
    return (
      <section className="search-results-section">
        <div className="search-results-container">
          <div className="search-results-loading">
            <p>Aranıyor...</p>
          </div>
        </div>
      </section>
    );
  }

  if (error) {
    return (
      <section className="search-results-section">
        <div className="search-results-container">
          <div className="search-results-error">
            <p>{error}</p>
          </div>
        </div>
      </section>
    );
  }

  if (results.length === 0) {
    return (
      <section className="search-results-section">
        <div className="search-results-container">
          <div className="search-results-empty">
            <p>"{query}" için sonuç bulunamadı.</p>
          </div>
        </div>
      </section>
    );
  }

  return (
    <section className="search-results-section">
      <div className="search-results-container">
        <div className="search-results-header">
          <h2 className="search-results-title">
            Arama Sonuçları ({results.length})
          </h2>
          {onClearSearch && (
            <button
              type="button"
              onClick={onClearSearch}
              className="search-results-clear-button"
            >
              Sıfırla
            </button>
          )}
        </div>
        <div className="search-results-grid">
          {results.map((result) => {
            const institutionId = Number(result.id);
            const isFavorite = Number.isFinite(institutionId) ? Boolean(favoriteIds?.has(institutionId)) : false;
            const isActionLoading = Number.isFinite(institutionId)
              ? Boolean(favoriteActionLoadingIds?.has(institutionId))
              : false;

            return (
            <Link
              key={result.id}
              href={getInstitutionDetailHref({
                id: result.id,
                slug: result.slug,
                source: result.source ?? null,
              })}
              className="featured-institution-card"
              aria-label={`${result.name} detayları`}
              onClick={onResultClick}
            >
              <div className="featured-institution-image-wrapper">
                <Image
                  src={result.imageUrl}
                  alt={result.name}
                  fill
                  className="featured-institution-image"
                  sizes="240px"
                  unoptimized
                />
                <div className="featured-institution-overlay" />
                {result.badge && (
                  <div className={`featured-institution-badge featured-institution-badge--${result.badge.color}`}>
                    <span className="featured-institution-badge-label">{result.badge.label}</span>
                  </div>
                )}
                <button
                  type="button"
                  className="featured-institution-favorite"
                  aria-label={isFavorite ? "Favorilerden kaldır" : "Favorilere ekle"}
                  disabled={isActionLoading || !Number.isFinite(institutionId) || (isAuthenticated && !favoritesEnabled)}
                  onClick={(e) => {
                    if (!onToggleFavorite || !Number.isFinite(institutionId)) {
                      e.preventDefault();
                      e.stopPropagation();
                      return;
                    }
                    onToggleFavorite(institutionId, e);
                  }}
                >
                  <Heart
                    className={
                      isFavorite ? "heart-favorite-icon heart-favorite-icon--active" : "heart-favorite-icon"
                    }
                  />
                </button>
              </div>
              <div className="featured-institution-content">
                <div className="featured-institution-location">
                  <svg width="12" height="14" viewBox="0 0 12 14" fill="none" xmlns="http://www.w3.org/2000/svg">
                    <path d="M6 0C2.69 0 0 2.69 0 6C0 10.5 6 14 6 14C6 14 12 10.5 12 6C12 2.69 9.31 0 6 0ZM6 8.25C4.76 8.25 3.75 7.24 3.75 6C3.75 4.76 4.76 3.75 6 3.75C7.24 3.75 8.25 4.76 8.25 6C8.25 7.24 7.24 8.25 6 8.25Z" fill="currentColor"/>
                  </svg>
                  <span>{result.location}</span>
                </div>
                <h3 className="featured-institution-name">{result.name}</h3>
                <p className="featured-institution-description" title={result.description}>{result.description}</p>
                <div className="featured-institution-footer">
                  <div className="featured-institution-rating">
                    <svg width="16" height="16" viewBox="0 0 16 16" fill="none" xmlns="http://www.w3.org/2000/svg">
                      <path d="M8 0L9.79611 5.52786L15.6085 5.52786L10.9062 8.94427L12.7023 14.4721L8 11.0557L3.29772 14.4721L5.09383 8.94427L0.391548 5.52786L6.20389 5.52786L8 0Z" fill="currentColor"/>
                    </svg>
                    <span>{result.rating}</span>
                  </div>
                  <span className="featured-institution-link">
                    İncele ›
                  </span>
                </div>
              </div>
            </Link>
            );
          })}
        </div>
      </div>
    </section>
  );
}

"use client";

import { GraduationCap, ChevronDown } from "lucide-react";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui";
import CategoryResultsCard from "./CategoryResultsCard";

interface CategoryResultsListProps {
  categoryName: string;
  subtitle?: string;
  results?: Array<{
    id: string;
    name: string;
    description: string;
    location: string;
    price: string | number;
    ageRange: string;
    rating: number;
    reviewCount: number;
    badges: string[];
    logoInitial?: string;
    logoColor?: string;
    imageUrl?: string;
    slug?: string;
  }>;
}

export default function CategoryResultsList({ categoryName, subtitle, results = [] }: CategoryResultsListProps) {
  return (
    <div className="category-results-list">
      <div className="category-results-header">
        <div className="category-results-header-left">
          <div className="category-results-title-wrapper">
            <GraduationCap size={24} className="category-results-title-icon" />
            <h2 className="category-results-title">Eğitim Kurumları</h2>
          </div>
          <p className="category-results-subtitle">
            {subtitle || "İstanbul bölgesinde öne çıkan en iyi eğitim kurumlarını inceleyin."}
          </p>
        </div>
        <div className="category-results-sort">
          <span className="category-results-sort-label">Sırala:</span>
          <Select defaultValue="recommended">
            <SelectTrigger className="category-results-sort-select">
              <SelectValue placeholder="Önerilenler" />
            </SelectTrigger>
            <SelectContent className="select-content">
              <SelectItem value="recommended" className="select-item">Önerilenler</SelectItem>
              <SelectItem value="rating" className="select-item">En Yüksek Puan</SelectItem>
              <SelectItem value="price-low" className="select-item">Fiyat: Düşükten Yükseğe</SelectItem>
              <SelectItem value="price-high" className="select-item">Fiyat: Yüksekten Düşüğe</SelectItem>
            </SelectContent>
          </Select>
        </div>
      </div>

      <div className="category-results-cards">
        {results.map((result) => (
          <CategoryResultsCard key={result.id} {...result} />
        ))}
      </div>
    </div>
  );
}

